import{_ as e,o as i,c as o,a2 as l}from"./chunks/framework.D7WGirly.js";const g=JSON.parse('{"title":"Kotlin 通信コア (Pixiv API) 仕様","description":"OkHttp と kotlinx.serialization による Pixiv API クライアント、署名、サイズ上限制限、うごイラ展開","frontmatter":{"title":"Kotlin 通信コア (Pixiv API) 仕様","description":"OkHttp と kotlinx.serialization による Pixiv API クライアント、署名、サイズ上限制限、うごイラ展開"},"headers":[],"relativePath":"dev/networking-core.md","filePath":"dev/networking-core.md","lastUpdated":1795329637000}'),d={name:"dev/networking-core.md"};function a(n,t,c,r,s,x){return i(),o("div",null,[...t[0]||(t[0]=[l('<h1 id="kotlin-通信コア-pixiv-api-仕様" tabindex="-1">Kotlin 通信コア (Pixiv API) 仕様 <a class="header-anchor" href="#kotlin-通信コア-pixiv-api-仕様" aria-label="Permalink to &quot;Kotlin 通信コア (Pixiv API) 仕様&quot;">​</a></h1><p><code>app/src/main/java/com/yunfie/illustia/data</code> 以下の <code>Kotlin*</code> / <code>Pixiv*</code> クラスが、Pixiv API のネットワーク通信・リクエスト署名・レスポンス JSON のパースを担います。以前は UniFFI 経由の Rust 実装でしたが、Kotlin に一本化しました。</p><hr><h2 id="バッファ上限仕様表" tabindex="-1">バッファ上限仕様表 <a class="header-anchor" href="#バッファ上限仕様表" aria-label="Permalink to &quot;バッファ上限仕様表&quot;">​</a></h2><p>うごイラ ZIP の安全読み込み上限です。Rust 版と同じ値を保っています。</p><table tabindex="0"><thead><tr><th style="text-align:left;">対象データ</th><th style="text-align:left;">上限サイズ</th><th style="text-align:left;">超過時の動作</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>うごイラ ZIP アーカイブ</strong></td><td style="text-align:left;"><strong>512 MiB</strong></td><td style="text-align:left;">ダウンロード中に <code>PixivApiException</code></td></tr><tr><td style="text-align:left;"><strong>うごイラ 単一フレーム</strong></td><td style="text-align:left;"><strong>32 MiB</strong></td><td style="text-align:left;">展開時に <code>PixivApiException</code></td></tr><tr><td style="text-align:left;"><strong>うごイラ 合計サイズ</strong></td><td style="text-align:left;"><strong>512 MiB</strong></td><td style="text-align:left;">展開時に <code>PixivApiException</code></td></tr><tr><td style="text-align:left;"><strong>うごイラ エントリ数</strong></td><td style="text-align:left;"><strong>10,000</strong></td><td style="text-align:left;">展開時に <code>PixivApiException</code></td></tr></tbody></table><hr><h2 id="モジュール構造-data" tabindex="-1">モジュール構造 (<code>data/</code>) <a class="header-anchor" href="#モジュール構造-data" aria-label="Permalink to &quot;モジュール構造 (`data/`)&quot;">​</a></h2><ul><li><code>KotlinPixivHttpClient.kt</code>: OkHttp ベースのクライアント。OAuth ログイン、Web ログイン URL、うごイラ準備、<code>PixivCall</code></li><li><code>PixivCallDecoders.kt</code> / <code>PixivCallDecoders2.kt</code>: エンドポイント別デコード（extension 関数）</li><li><code>PixivApiDtos.kt</code>: kotlinx.serialization のワイヤ DTO と OAuth / 小説 JSON パーサ</li><li><code>PixivApiDecoder.kt</code>: 作品・ユーザー・アカウント系の DTO → モデル変換</li><li><code>PixivIllustMapper.kt</code>: IllustDto の URL フォールバックを含むマッピング</li><li><code>PixivActivityDecoder.kt</code>: コメント・通知・スタンプ・トレンド・スポットライト</li><li><code>PixivNovelDecoder.kt</code>: 小説・マンガ・シリーズ</li><li><code>PixivRequestSigner.kt</code>: 署名ヘッダ生成</li><li><code>UgoiraCache.kt</code> / <code>UgoiraValidation.kt</code> / <code>UgoiraFiles.kt</code>: うごイラ ZIP のダウンロード・検証・展開</li></ul><hr><h2 id="リクエスト署名" tabindex="-1">リクエスト署名 <a class="header-anchor" href="#リクエスト署名" aria-label="Permalink to &quot;リクエスト署名&quot;">​</a></h2><p>公式アプリを模したヘッダ（<code>app-os</code> / <code>app-version</code> / <code>Accept-Language</code>）を付与します。<code>x-client-hash</code> は「現在時刻 + 共有シークレット」の MD5 で、これが無いと API 側に弾かれます。認証付きリクエストには <code>Accept: application/json</code> と <code>Referer</code> も付与します。</p><p>うごイラ展開では、パストラバーサル（<code>..</code>・絶対パス）・シンボリックリンク・重複エントリ・必須フレーム欠落を拒否します。</p>',13)])])}const P=e(d,[["render",a]]);export{g as __pageData,P as default};
